import {createServer} from 'node:http';
export async function accountEmployerFixture({mode='signup',existing=false,code='123456',failLogin=false}={}){
 const known=new Map(existing?[['synthetic@example.test','known-synthetic-password']]:[]),sessions=new Map();let signupCount=0,loginCount=0,resetCount=0,verificationCount=0;
 const app=email=>`<h1>Engineering intern</h1><p data-employer>Example Labs</p><span data-authenticated-email="${email}">Signed in as ${email}</span><p>Application form ready for the verified applicant.</p>`;
 const server=createServer(async(req,res)=>{
  const url=new URL(req.url,'http://localhost'),cookie=(req.headers.cookie||'').match(/hub_fixture=([^;]+)/)?.[1],email=sessions.get(cookie);res.setHeader('content-type','text/html');
  if(url.pathname==='/reset'){resetCount++;res.end('Reset is forbidden in fixture tests');return;}
  if(url.pathname==='/signup'||url.pathname==='/signin'){let raw='';for await(const chunk of req)raw+=chunk;const data=new URLSearchParams(raw),candidate=data.get('email'),password=data.get('password');if(url.pathname==='/signup'){signupCount++;if(known.has(candidate)){res.end('exists');return;}known.set(candidate,password);res.end('verify');return;}loginCount++;if(failLogin||known.get(candidate)!==password){res.end('invalid');return;}sessions.set('authorized',candidate);res.setHeader('set-cookie','hub_fixture=authorized; Path=/; HttpOnly; SameSite=Strict');res.end('ok');return;}
  if(url.pathname==='/verify-action'){verificationCount++;let raw='';for await(const chunk of req)raw+=chunk;if(new URLSearchParams(raw).get('code')!==code){res.end('invalid');return;}sessions.set('authorized','synthetic@example.test');res.setHeader('set-cookie','hub_fixture=authorized; Path=/; HttpOnly; SameSite=Strict');res.end('ok');return;}
  if(url.pathname==='/verify'){res.end(`<h1>Verify your email</h1><p data-employer>Example Labs</p><p>Check your email for the employer verification code.</p><form id="f"><label>Verification code<input name="code" autocomplete="one-time-code"></label><button>Verify email</button></form><script>f.onsubmit=async e=>{e.preventDefault();const result=await(await fetch('/verify-action',{method:'POST',body:new URLSearchParams(new FormData(f))})).text();if(result==='ok')location.href='/jobs/1';else document.body.append('Invalid code')};</script>`);return;}
  if(email){res.end(app(email));return;}
  const login=url.searchParams.get('login')==='1'||mode==='login',button=login?'Sign in':'Create account';
  res.end(`<h1>Engineering intern</h1><p data-employer>Example Labs</p>${mode==='captcha'?'<p>CAPTCHA: Verify you are human</p>':''}<form id="f"><label>Email<input type="email" name="email"></label><label>Password<input type="password" name="password"></label>${login?'':'<label><input type="password" name="confirm">Confirm password</label><label><input type="checkbox" required>I agree to the employer privacy notice</label>'}<button>${button}</button></form><a href="/reset">Forgot password</a><a href="/jobs/1?login=1">Sign in</a>${mode==='guest'?'<button id="guest">Continue as guest</button>':''}<script>${mode==='guest'?`guest.onclick=()=>document.body.innerHTML='<h1>Engineering intern</h1><p data-employer>Example Labs</p><p>Guest application form</p>';`:''}${mode==='parser'?`document.querySelector('input[name=password]').oninput=()=>setTimeout(()=>document.querySelector('input[name=email]').value='wrong@example.test',20);`:''}f.onsubmit=async e=>{e.preventDefault();const result=await(await fetch('${login?'/signin':'/signup'}',{method:'POST',body:new URLSearchParams(new FormData(f))})).text();if(result==='verify')location.href='/verify';else if(result==='ok')location.href='/jobs/1';else document.body.append(result==='exists'?'Account already exists':'Incorrect password');};</script>`);
 });
 await new Promise(resolve=>server.listen(0,'127.0.0.1',resolve));return {url:`http://127.0.0.1:${server.address().port}/jobs/1`,counts:()=>({signupCount,loginCount,resetCount,verificationCount}),known,close:()=>new Promise(resolve=>server.close(resolve))};
}
